/** Resolves a client source or import to its top-level owner. */
export function clientOwner(file) {
  return file.startsWith("client/") ? file.split("/")[1] : undefined;
}

/** Checks every client import and the permitted owner graph for cycles. */
export function checkClientDependencyMatrix(edges, matrix, files = []) {
  const violations = [];
  const owners = new Set(Object.keys(matrix));
  const visiting = new Set();
  const visited = new Set();

  function visit(owner, path) {
    if (visiting.has(owner)) {
      violations.push({
        from: "tools/check/client-dependency-matrix.json",
        to: [...path, owner].join(" -> "),
        reason: "Client dependency matrix contains a cycle"
      });
      return;
    }
    if (visited.has(owner)) return;
    visiting.add(owner);
    for (const target of matrix[owner] ?? []) {
      if (!owners.has(target)) {
        violations.push({
          from: `client/${owner}`,
          to: `client/${target}`,
          reason: "Unknown client dependency matrix owner"
        });
        continue;
      }
      visit(target, [...path, owner]);
    }
    visiting.delete(owner);
    visited.add(owner);
  }

  for (const owner of owners) visit(owner, []);
  for (const file of files) {
    const owner = clientOwner(file);
    if (owner && !owners.has(owner)) {
      violations.push({
        from: file,
        to: "tools/check/client-dependency-matrix.json",
        reason: "Client source has no dependency matrix owner"
      });
    }
  }
  for (const edge of edges) {
    const from = clientOwner(edge.from);
    if (!from) continue;
    const to = clientOwner(edge.to);
    if (!owners.has(from) || (to && !owners.has(to))) {
      violations.push({
        ...edge,
        reason: "Client source has no dependency matrix owner"
      });
    } else if (to && from !== to && !matrix[from].includes(to)) {
      violations.push({
        ...edge,
        reason: "Client dependency matrix disallows this import"
      });
    }
  }
  return violations;
}

/** Checks workspace manifest edges against the same client owner matrix. */
export function checkClientManifestMatrix(manifests, matrix) {
  const ownerByPackage = new Map(
    manifests.map(({ owner, manifest }) => [manifest.name, owner])
  );
  const violations = [];
  for (const { owner, manifest } of manifests) {
    const dependencies = {
      ...manifest.dependencies,
      ...manifest.peerDependencies,
      ...manifest.devDependencies
    };
    for (const packageName of Object.keys(dependencies)) {
      const target = ownerByPackage.get(packageName);
      if (target && target !== owner && !matrix[owner]?.includes(target)) {
        violations.push({
          from: `client/${owner}/package.json`,
          to: `client/${target}/package.json`,
          reason: "Client dependency matrix disallows this workspace dependency"
        });
      }
    }
  }
  return violations;
}
import fs from "node:fs";
import path from "node:path";
import { execFileSync } from "node:child_process";
import { fileURLToPath } from "node:url";
import ts from "typescript";

const root = path.resolve(
  path.dirname(fileURLToPath(import.meta.url)),
  "../.."
);
const inventory = JSON.parse(
  fs.readFileSync(
    path.join(root, "docs/architecture/type-ownership-inventory.json"),
    "utf8"
  )
);
const printer = ts.createPrinter({ removeComments: true });
const failures = [];
let enums = 0;
let retiredEnums = 0;
const retiredCacheModule = "client/layout/layers/cache/cache.type.ts";

/** Collects runtime enums without comments or formatting differences. */
function declarations(file, text) {
  const source = ts.createSourceFile(file, text, ts.ScriptTarget.Latest, true);
  const result = new Map();
  const visit = (node) => {
    if (ts.isEnumDeclaration(node))
      result.set(
        node.name.text,
        printer.printNode(ts.EmitHint.Unspecified, node, source)
      );
    ts.forEachChild(node, visit);
  };
  visit(source);
  return result;
}

for (const module of inventory.modules) {
  const candidates = new Map();
  for (const destination of module.destinations) {
    const file = path.join(root, destination);
    if (!fs.existsSync(file)) {
      failures.push(`Missing destination: ${destination}`);
      continue;
    }
    for (const [name, declaration] of declarations(
      destination,
      fs.readFileSync(file, "utf8")
    ))
      candidates.set(name, declaration);
  }
  if (module.path.endsWith(".svelte")) continue;
  const original = execFileSync(
    "git",
    ["show", `${inventory.baseline}:${module.path}`],
    { cwd: root, encoding: "utf8" }
  );
  for (const [name, declaration] of declarations(module.path, original)) {
    if (module.path === retiredCacheModule && name === "CacheKey") {
      if (
        module.disposition !== "removed" ||
        module.destinations.length !== 0 ||
        fs.existsSync(path.join(root, "client/shell/layers/cache"))
      ) failures.push("Retired cache contract must not be restored");
      retiredEnums++;
      continue;
    }
    enums++;
    if (candidates.get(name) !== declaration)
      failures.push(`Runtime enum changed: ${module.path}:${name}`);
  }
}

for (const file of [
  "package.json",
  "package-lock.json",
  "tools/alias-map.json"
]) {
  const text = fs.readFileSync(path.join(root, file), "utf8");
  if (/@21n\/(types|shared-types)"|"(?:client|shared)\/types"/.test(text))
    failures.push(`Retired package in ${file}`);
}
for (const failure of failures) console.error(failure);
console.log(
  `Type ownership: ${inventory.modules.length} module dispositions, ${enums} unchanged runtime enums, ${retiredEnums} audited retired enums, ${failures.length} failures.`
);
process.exitCode = failures.length ? 1 : 0;

