import type { Resource } from "@nucleum/datafn/resource.enum";
import type { ResourceActionType } from "@nucleum/schema/legacy/resource-action.enum";

/** Application command execution supplied by the composing shell. */
export interface CommandHost {
  resolveAction(slug: string): IAction | null;
  runAction(
    slug: string,
    params?: {
      componentParams?: any;
      isReturnIfComponent?: boolean;
      searchParams?: Record<string, string | boolean | number>;
    }
  ): any;
  runResourceAction(
    resource: Resource,
    action: ResourceActionType,
    params?: any
  ): any;
}
let commandHost: CommandHost | undefined;
/** Installs the product command executor before mounting application surfaces. */
export function configureCommandHost(host: CommandHost) {
  commandHost = host;
}
/** Requires the composing shell to supply command behavior. */
export function requireCommandHost(): CommandHost {
  if (!commandHost) throw new Error("Command host has not been configured");
  return commandHost;
}
/**
 * Product-wide navigation chrome configuration shared with the application
 * shell. The composition root installs the full product config; the shell only
 * reads the narrow navigation fields it needs, keeping product assembly in
 * `client/products`.
 */
export type ProductNavConfig = {
  appMenu: string[];
  appMenuPt: string[];
  homePath: string;
  homePathPt: string;
  isShowCaptureOnMobile?: boolean;
};

let productConfig: ProductNavConfig | undefined;

/**
 * Installs the resolved product navigation config from `configure-hosts.ts`.
 */
export function configureProductConfigHost(value: ProductNavConfig) {
  productConfig = value;
}

/**
 * Reads the installed product navigation config. Throws when the composition
 * root has not configured the host.
 */
export function requireProductConfig(): ProductNavConfig {
  if (!productConfig)
    throw new Error("Product config host has not been configured");
  return productConfig;
}
