name: Tests

on:
  push:
    branches:
      - dev
      - main
  pull_request:
    branches:
      - dev
      - main
  workflow_dispatch: {}

concurrency:
  group: tests-${{ github.workflow }}-${{ github.head_ref || github.ref }}
  cancel-in-progress: true

jobs:
  app-checks:
    runs-on: ubuntu-latest
    permissions:
      contents: read
    steps:
      - name: Checkout
        uses: actions/checkout@v4
      - name: Setup Node
        uses: actions/setup-node@v4
        with:
          node-version: 20
          cache: npm
      - name: Install dependencies
        run: npm install --legacy-peer-deps
      - name: Check architecture boundaries
        run: npm run check:architecture
      - name: Run app checks
        run: npm run check:apps

  vitest:
    runs-on: ubuntu-latest
    permissions:
      contents: read
      actions: write
    steps:
      - name: Checkout
        uses: actions/checkout@v4
      - name: Setup Node
        uses: actions/setup-node@v4
        with:
          node-version: 20
          cache: npm
      - name: Install dependencies
        run: npm install --legacy-peer-deps
      - name: Run unified test suite
        run: npm run test
      - name: Upload coverage to Codecov
        uses: codecov/codecov-action@v4
        with:
          token: ${{ secrets.CODECOV_TOKEN }}
          files: |
            coverage/**/coverage-final.json
            tests/coverage/**/coverage-final.json
          flags: vitest
          disable_search: true
      - name: Upload coverage artifacts
        if: always()
        uses: actions/upload-artifact@v4
        with:
          name: coverage
          path: coverage
          retention-days: 14

  playwright-smoke:
    runs-on: ubuntu-latest
    needs:
      - app-checks
      - vitest
    timeout-minutes: 30
    permissions:
      contents: read
      actions: write
    strategy:
      fail-fast: false
      matrix:
        include:
          - product: nucleum
            workspace: "@nucleum/app"
            port: 5050
            domain: local.nucleum.app
          - product: pointron
            workspace: pointron
            port: 5001
            domain: local.pointron.app
          - product: memotron
            workspace: "@memotron/app"
            port: 5002
            domain: local.memotron.app
    steps:
      - name: Checkout
        uses: actions/checkout@v4
      - name: Setup Node
        uses: actions/setup-node@v4
        with:
          node-version: 20
          cache: npm
      - name: Install dependencies
        run: npm install --legacy-peer-deps
      - name: Install Playwright browsers
        run: npx playwright install --with-deps
        working-directory: apps/e2e-playwright
      - name: Map HTTPS local domains
docs/architecture/type-ownership.md:3:Current type-placement contract. If this file disagrees with `docs/architecture/type-ownership-inventory.json` or `node tools/check/type-ownership.mjs`, the checker wins. Update the inventory in the same change that moves a type module.
docs/architecture/type-ownership.md:53:`node tools/check/type-ownership.mjs` checks every recorded destination in [type-ownership-inventory.json](type-ownership-inventory.json) and compares runtime enum declarations to that baseline. One audited retirement is recorded there: the disconnected shell cache `CacheKey` enum. No other runtime-enum retirement is exempt.
docs/architecture/history/tidy-478-type-ownership.md:65:`node tools/check/type-ownership.mjs` checks all recorded destinations and compares 199 runtime enum declarations to the baseline. `npm run check:architecture`, `npm run check:no-fixed-test-waits`, `npm run check:no-legacy-runtime`, `npm run lint` and the Turbo build graph dry-run pass. Lint has no package lint scripts and runs the configured static build prerequisite; it is not a claim of repository-wide formatting or ESLint coverage. Existing source aliases remain build-time dependencies; they are not indiscriminately added as workspace dependencies, which would create Turbo cycles. Contract consumers use the schema dependency and the existing frontend package/alias model.

