import assert from "node:assert/strict";
import test from "node:test";
import { checkWorkspaceExports, resolveExport } from "./workspace-exports.mjs";

test("filesystem aliases cannot bypass missing package exports", () => {
  const packages = [{ name: "@example/state", directory: "client/state", exports: { "./public/*": "./public/*" } }];
  const imports = [{ from: "client/shell/page.ts", specifier: "@example/state/private/host" }];
  assert.equal(checkWorkspaceExports(imports, packages).length, 1);
  packages[0].exports["./private/*"] = "./private/*";
  assert.deepEqual(checkWorkspaceExports(imports, packages), []);
});

test("specific exclusions win over wildcard exports", () => {
  assert.equal(resolveExport({ "./*": "./*", "./private/*": null }, "./private/secret"), null);
  assert.equal(resolveExport({ "./*.js": "./*.ts" }, "./store.js"), "./store.ts");
});

/** Resolves exact and wildcard public subpaths, honoring explicit exclusions. */
export function resolveExport(exports, subpath) {
  if (!exports || typeof exports !== "object") return undefined;
  if (Object.hasOwn(exports, subpath)) return exports[subpath];
  const pattern = Object.keys(exports).filter((key) => key.includes("*")).sort((a, b) => b.length - a.length).find((key) => {
    const [prefix, suffix] = key.split("*");
    return subpath.startsWith(prefix) && subpath.endsWith(suffix);
  });
  if (!pattern) return undefined;
  const [prefix, suffix] = pattern.split("*");
  const value = subpath.slice(prefix.length, suffix ? -suffix.length : undefined);
  const target = exports[pattern];
  return typeof target === "string" ? target.replaceAll("*", value) : target;
}

/** Detects package imports concealed by filesystem aliases instead of public exports. */
export function checkWorkspaceExports(imports, packages) {
  const violations = [];
  for (const { from, specifier } of imports) {
    if (/\.(test|spec|stories)\./.test(from) || from.includes("/tests/")) continue;
    const owner = packages.find((item) => specifier === item.name || specifier.startsWith(`${item.name}/`));
    if (!owner || from.startsWith(`${owner.directory}/`)) continue;
    const subpath = specifier === owner.name ? "." : `.${specifier.slice(owner.name.length)}`;
    const target = resolveExport(owner.exports, subpath);
    if (target === undefined || target === null) violations.push({ from, to: specifier, reason: "Workspace import is not exported" });
  }
  return violations;
}

