import { afterEach, expect, it, vi } from "vitest";
import { recoverInvalidAccountSession } from "./session-recovery";

const calls = vi.hoisted(() => ({ signout: vi.fn(), goto: vi.fn() }));
vi.mock("@nucleum/client/runtime/account/session-cleanup", () => ({ signout: calls.signout }));
vi.mock("@nucleum/client/runtime/navigation/navigation-request", () => ({ goto: calls.goto }));

afterEach(() => {
  vi.unstubAllGlobals();
  vi.clearAllMocks();
});

it("awaits cleanup before requesting login navigation and reloading", async () => {
  const order: string[] = [];
  calls.signout.mockImplementation(async () => { await Promise.resolve(); order.push("cleanup"); });
