    const current = syncServer;
    syncServer = undefined;
    if (!current) {
      return;
    }
    const server = await current.catch(() => undefined);
    await server?.close();
  };

  return {
    auth,
    getSyncServer,
    regionId,
    corsOrigins,
    observability,
    infra,
    deployment,
    integrations,
    close
