import { createNucleumAuthFnTransportAuth } from "@nucleum/client/runtime/account/auth";
import { logger } from "@nucleum/client/runtime/logging/logger";

/** Builds authenticated DataFn HTTP transport options. */
export async function createNucleumDatafnHttpOptions(
  input: {
    publicLinkToken?: string;
  } = {}
): Promise<DatafnHttpTransportOptions> {
  return {
    auth: await createNucleumAuthFnTransportAuth({
      plugins: input.publicLinkToken
        ? [createDatafnPublicLinkAuthPlugin(input.publicLinkToken)]
        : []
    }),
    onError: ({ endpoint, status, result }) => {
      logger.error({
        at: "datafn.remote.error",
        endpoint,
        status,
        result
      });
    }
  };
}
import {
  type DatafnStorageAdapter,
  IndexedDbStorageAdapter
} from "@datafn/client";
import type { Product } from "@nucleum/client/config/product.type";
import { nucleumDatafnSchema } from "@nucleum/schema";
import { deleteIndexedDbDatabase } from "@nucleum/persistence/indexeddb/delete-database";

/** Closes a runtime storage adapter when one is installed. */
export async function closeNucleumDatafnRuntimeStorage(
  storage: DatafnStorageAdapter | undefined
) {
  if (!storage) return;
  await storage.close();
}

/** Deletes the selected local data and search databases. */
export async function deleteDatafnLocalClone(storageDbName: string) {
  await Promise.all([
    deleteIndexedDbDatabase(storageDbName),
    deleteIndexedDbDatabase(`${storageDbName}-search`)
  ]);
}

/** Names a product DataFn database before namespace scoping. */
export function resolveDatafnBaseDbName(input: {
  product: Product;
  env?: string;
}) {
  const product = input.product.toString().trim().toLowerCase();
  const env = input.env?.toString().trim().toLowerCase() || "dev";
  return `nucleum-datafn-${env}-${product}`;
}

/** Names the namespace-scoped DataFn database. */
export function resolveDatafnStorageDbName(input: {
  product: Product;
  namespace: string;
  env?: string;
}) {
  return `${resolveDatafnBaseDbName(input)}_${input.namespace.replace(/:/g, "_")}`;
}

/** Creates namespace-scoped IndexedDB storage. */
export function createDatafnStorage(input: {
  product: Product;
  namespace: string;
  env?: string;
}) {
  const storage = IndexedDbStorageAdapter.createForNamespace(
    resolveDatafnBaseDbName(input),
    input.namespace,
    undefined,
    nucleumDatafnSchema
  );
  return {
    storage,
    dbName: storage.dbName
  };
}

const nodeMdChildOrderMigrationId = "kv:migration:node-md-child-order-v1";

/** Migrates stored node child order once per local database. */
export async function migrateDatafnNodeMdChildOrder(
  storage?: DatafnStorageAdapter | null
) {
  if (!storage) return;
  const marker = await storage
    .getRecord("kv", nodeMdChildOrderMigrationId)
    .catch(() => null);
  if (marker) return;
  const records = await storage.listRecords("node");
  let migratedCount = 0;
  for (const record of records) {
    if (!("children" in record)) continue;
    const { children, ...nextRecord } = record;
    if (!Array.isArray(nextRecord.mdChildOrder) && Array.isArray(children)) {
      nextRecord.mdChildOrder = children;
      migratedCount++;
    }
    await storage.upsertRecord("node", nextRecord);
  }
  await storage.upsertRecord("kv", {
    id: nodeMdChildOrderMigrationId,
    value: true,
    migratedCount,
    migratedAt: new Date().toISOString()
  });
}
import { logger } from "@nucleum/client/runtime/logging/logger";
import type { ClipperExtensionEvent } from "@nucleum/client/runtime/extensions/clipper-event.type";
import type { ExtensionEvent } from "@nucleum/client/runtime/extensions/extension-event.enum";
import { sendToBackground, type PlasmoMessaging } from "@plasmohq/messaging";

type ExtensionRelayMessage = {
  data?: unknown;
  event: ClipperExtensionEvent | ExtensionEvent;
};

type StoredTabPayload = {
  tab?: chrome.tabs.Tab;
};

const sendBackgroundMessage = sendToBackground as PlasmoMessaging.SendFx<
  ClipperExtensionEvent | ExtensionEvent
>;

/**
 * @param message
 * @param tabId
 * @returns
 */
export async function relayToContentScript(
  message: ExtensionRelayMessage,
  tabId?: number
): Promise<unknown> {
  if (!tabId) {
    const tabData = (await chrome.storage.local.get("tab")) as StoredTabPayload;
    tabId = tabData?.tab?.id;
  }
  if (typeof tabId !== "number") {
    throw new Error("Unable to resolve content script tab id");
  }
  return new Promise((resolve, reject) => {
    chrome.tabs.sendMessage(tabId, message, (response: unknown) => {
      if (chrome.runtime.lastError) {
        reject(chrome.runtime.lastError);
      } else {
        resolve(response);
      }
    });
  });
}

/** Relay to side panel. */
export async function relayToSidePanel(message: ExtensionRelayMessage) {
  chrome.runtime.sendMessage(message);
}

/** Relay to background script. */
export async function relayToBackgroundScript(
  message: ExtensionRelayMessage
): Promise<any> {
  try {
    logger.debug({
      at: "relayToBackgroundScript",
      message,
      chromeRuntimeId: chrome.runtime.id
    });

    const timeoutPromise = new Promise<never>((_, reject) => {
      setTimeout(() => {
        reject(
          new Error("Background script communication timeout after 10 seconds")
        );
      }, 10000);
    });

    const backgroundPromise = sendBackgroundMessage<
      typeof message.data,
      unknown
    >({
      name: message.event,
      body: message.data,
      extensionId: chrome.runtime.id
    });

    const response = await Promise.race([backgroundPromise, timeoutPromise]);

    logger.log({
      at: "relayToBackgroundScript - response",
      response
    });
    return response;
  } catch (error) {
    logger.error({
      at: "relayToBackgroundScript - error",
      error
    });
    throw error;
  }
}
import { parse } from "@21n/shared-utils/json.utils";

/** Decodes only native messages from the current webview window and origin. */
export function parseNativeMessage(
  event: MessageEvent
): Record<string, any> | undefined {
  if (event?.data?.type !== "SWIFT_MESSAGE" || event.source !== window) return;
  if (event.origin !== window.location.origin && event.origin !== "null")
    return;
  const payload = event.data.payload;
  if (typeof payload !== "string" || !payload.trim().startsWith("{")) return;
  return parse(payload);
}
