export function resolveHost() {
  const nativeWebOrigin = resolveNativeConfigUrl("webOrigin");
  if (nativeWebOrigin) return nativeWebOrigin.hostname;

  if (
    typeof window !== "undefined" &&
    (window.location.protocol === "http:" ||
      window.location.protocol === "https:")
  ) {
    return window.location.hostname;
  }
  return (
    import.meta.env?.VITE_HOST ??
    (typeof window !== "undefined" ? window.location.hostname : "localhost")
  );
}

export function resolveAccountBaseUrl(region: string) {
  const nativeAccountBaseUrl = resolveNativeAccountBaseUrl(region);
  if (nativeAccountBaseUrl) {
    return nativeAccountBaseUrl;
  }

  const regionalTemplate = import.meta.env?.VITE_ACCOUNT_BASE_URL_TEMPLATE;
  if (regionalTemplate) {
    return renderAccountBaseUrlTemplate(regionalTemplate, region);
  }

  const explicitBaseUrl = import.meta.env?.VITE_ACCOUNT_BASE_URL;
  if (explicitBaseUrl) {
    return explicitBaseUrl.replace(/\/$/, "");
  }

  const host = resolveHost().toLowerCase();
  if (isLoopbackHost(host)) {
    return "http://localhost:3000";
  }

  const accountEnv = resolveAccountEnvironment(host);
  const accountDomain = resolveAccountDomain(host);
  const normalizedRegion = normalizeAccountRegion(region);
  const envSuffix = accountEnv === "live" ? "" : `-${accountEnv}`;
  return `https://account-${normalizedRegion}${envSuffix}.${accountDomain}`;
}

export function resolveAccountCookiePrefix(region = "insouth") {
  const configured = import.meta.env?.VITE_ACCOUNT_COOKIE_PREFIX?.trim();
  if (configured) return configured;

  const baseUrl = resolveAccountBaseUrl(region);
  const accountEnv = resolveAccountEnvironmentFromAccountBaseUrl(baseUrl);
  if (accountEnv === "local") return "nucleus_local";
  if (accountEnv === "pre") return "nucleus_pre";
  return "nucleus";
}
import { createDynamoDbRegionLookupStore } from '@authfn/lookup-dynamodb';
import type { ConditionalKVStoreAdapter } from '@superfunctions/db';

export function createAccountLookupStore(): ConditionalKVStoreAdapter | undefined {
  const tableName = process.env.AUTHFN_REGION_LOOKUP_TABLE;
  if (!tableName) {
    return undefined;
  }

  return createDynamoDbRegionLookupStore({
    tableName,
    region: process.env.AWS_REGION ?? process.env.AWS_DEFAULT_REGION ?? 'us-east-1',
    endpoint: process.env.DYNAMODB_ENDPOINT,
    consistentRead: process.env.AUTHFN_REGION_LOOKUP_CONSISTENT_READ === 'true'
  });
}
import fs from 'node:fs';
import path from 'node:path';
import process from 'node:process';
import { spawnSync } from 'node:child_process';
import { missingHyperdriveIds, renderWranglerConfig } from './wrangler-config.mjs';

const serviceRoot = path.resolve(import.meta.dirname, '..');
const config = JSON.parse(fs.readFileSync(path.join(serviceRoot, 'config/environments.json'), 'utf8'));

const environment = normalizeEnvironment(process.argv[2] ?? 'dev');
const regionsArg = process.argv.find((arg) => arg.startsWith('--regions='))?.split('=')[1];
const regions = regionsArg ? regionsArg.split(',').map((entry) => entry.trim()).filter(Boolean) : Object.keys(config.regions);
const dryRun = process.argv.includes('--dry-run');

if (!environment || !config.environments[environment]) {
  console.error('Usage: node scripts/deploy.mjs <dev|pre|live> [--regions=insouth,useast,euwest] [--dry-run]');
  process.exit(1);
}

const envConfig = config.environments[environment];
const missing = missingHyperdriveIds(config, environment, regions);

if (missing.length > 0) {
  console.error(`Cannot deploy ${environment}; configure these Hyperdrive IDs first:`);
  for (const item of missing) {
    console.error(`- ${item}`);
  }
  process.exit(1);
}

const wranglerConfig = renderWranglerConfig(serviceRoot, config, environment);

if (!dryRun) {
  for (const region of regions) {
    migrateDatafnDatabase(region);
  }
}

run('npm', ['run', 'build']);
run('wrangler', ['deploy', '--config', wranglerConfig, '--env', envConfig.lookupWorkerEnv, ...(dryRun ? ['--dry-run'] : [])]);

for (const region of regions) {
  const wranglerEnv = envConfig.regions[region].wranglerEnv;
  run('wrangler', ['deploy', '--config', wranglerConfig, '--env', wranglerEnv, ...(dryRun ? ['--dry-run'] : [])]);
}

function migrateDatafnDatabase(region) {
  const variable = `DATAFN_${region}_DATABASE_URL`
    .toUpperCase()
    .replace(/[^A-Z0-9]+/g, '_');
  const databaseUrl = process.env[variable]?.trim();
  if (!databaseUrl) {
    console.error(`Cannot deploy ${environment}/${region}; set the ${variable} secret.`);
    process.exit(1);
  }
  run('npm', ['run', 'datafn:migrate'], {
    DATAFN_DATABASE_URL: databaseUrl
  });
}

function run(command, args, env = {}) {
  console.log(`\n$ ${command} ${args.join(' ')}`);
  const result = spawnSync(command, args, {
    cwd: serviceRoot,
    stdio: 'inherit',
    env: {
      ...process.env,
      ...env
    },
    shell: process.platform === 'win32'
  });
  if (result.status !== 0) {
    process.exit(result.status ?? 1);
  }
}
